def lonely_tree_nodes(root):
 answer=[];stack=[root]
 while stack:
  node=stack.pop()
  if not node:continue
  if node.left and not node.right:answer.append(node.left.val)
  if node.right and not node.left:answer.append(node.right.val)
  stack.extend((node.left,node.right))
 return answer

